// Aerial cinema index — record JAH-GGNS-CAMERADRONE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"flight_min": 34, "sensor_mp": 48, "price_usd": 800};
var value = (m.flight_min*m.sensor_mp/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-CAMERADRONE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-CAMERADRONE-000001|' + value.toFixed(2) + ' cinema index');

